1	// Package rollup downsamples a time series into fixed windows aligned to
2	// the Unix epoch, and merges rollups that share a window size.
3	//
4	// A Roller is safe for concurrent use: samples may be filed, windows read,
5	// and rollers merged from multiple goroutines at once. Every read observes
6	// an internally consistent snapshot, and a merge or batch is visible to
7	// other callers either in full or not at all.
8	package rollup
9	
10	import (
11		"errors"
12		"math"
13		"math/bits"
14		"sync"
15		"sync/atomic"
16		"time"
17	)
18	
19	// ErrOutOfOrder is returned by Add when a sample predates the most recent
20	// sample the roller has already accepted.
21	var ErrOutOfOrder = errors.New("rollup: out of order")
22	
23	// ErrWindowMismatch is returned by Merge when the two rollers use different
24	// window sizes.
25	var ErrWindowMismatch = errors.New("rollup: window mismatch")
26	
27	// Sample is one record in a batch passed to AddBatch: a value observed at
28	// one instant.
29	type Sample struct {
30		At    time.Time
31		Value float64
32	}
33	
34	// Window holds the aggregate statistics of the samples filed into one
35	// window. Start is the window's left-closed, right-open lower bound.
36	type Window struct {
37		Start time.Time
38		Count int64
39		Sum   float64
40		Min   float64
41		Max   float64
42	}
43	
44	// Roller aggregates samples into fixed windows of a single size.
45	//
46	// The zero value is not usable; build one with New. All methods are safe
47	// to call concurrently from multiple goroutines.
48	type Roller struct {
49		// mu guards buckets, back, latest, and hasAny. window and id are
50		// fixed at construction and read without the lock.
51		//
52		// buckets is one flat slice kept sorted by window start: samples
53		// arrive in non-decreasing time order, so Add appends in amortized
54		// constant time, Windows reads out without re-sorting, and Merge is
55		// a single linear pass over both sides.
56		//
57		// back is a second sorted slice holding backfilled windows: a sample
58		// that lands before the newest window opens its bucket here, so the
59		// insert never shifts the tail of buckets and mass backfills stay
60		// cheap. back is folded into buckets once it is large enough for
61		// the merge to amortize. Every read consults both slices, and no
62		// window start appears in both at the same time.
63		mu      sync.RWMutex
64		id      uint64
65		window  time.Duration
66		buckets []Window
67		back    []Window
68		latest  time.Time
69		hasAny  bool
70	}
71	
72	// idGen hands out unique roller IDs so Merge can lock two rollers in a
73	// consistent order and concurrent cross-merges cannot deadlock.
74	var idGen atomic.Uint64
75	
76	// New builds a roller with the given window size. It panics with
77	// "rollup: bad window" if window is not positive.
78	func New(window time.Duration) *Roller {
79		if window <= 0 {
80			panic("rollup: bad window")
81		}
82		return &Roller{
83			id:     idGen.Add(1),
84			window: window,
85		}
86	}
87	
88	// startOf returns the start of the window containing at, aligned to an
89	// integer multiple of the window size since the Unix epoch. The arithmetic
90	// is exact for any time value, including ones whose nanosecond offset from
91	// the epoch does not fit in an int64.
92	func (r *Roller) startOf(at time.Time) time.Time {
93		sec := at.Unix()
94		nsec := int64(at.Nanosecond())
95		w := r.window.Nanoseconds()
96		if sec >= -9223372036 && sec <= 9223372035 {
97			// sec*1e9+nsec fits in an int64. Rounding a negative ns down to
98			// a window multiple can reach ns-(w-1), so stay on the fast
99			// path only when that product cannot overflow either.
100			if ns := sec*1e9 + nsec; ns >= math.MinInt64+w-1 {
101				start := ns / w
102				if ns%w != 0 && ns < 0 {
103					start--
104				}
105				return time.Unix(0, start*w).UTC()
106			}
107		}
108		return windowStartWide(sec, nsec, w)
109	}
110	
111	// windowStartWide is the 128-bit slow path of startOf, for times whose
112	// nanosecond offset from the epoch overflows an int64.
113	func windowStartWide(sec, nsec, w int64) time.Time {
114		// t = sec*1e9 + nsec as a 128-bit two's-complement value (hi, lo).
115		uhi, ulo := bits.Mul64(uint64(sec), uint64(1e9))
116		if sec < 0 {
117			uhi -= 1e9
118		}
119		hi := int64(uhi)
120		lo := ulo + uint64(nsec)
121		if lo < ulo {
122			hi++
123		}
124		// Round t down to a multiple of w: start = t - floorMod(t, w).
125		rem := floorMod128(hi, lo, w)
126		if lo < rem {
127			hi--
128		}
129		lo -= rem
130		// Split start into whole seconds and nanoseconds.
131		ns := floorMod128(hi, lo, 1e9)
132		if lo < ns {
133			hi--
134		}
135		lo -= ns
136		return time.Unix(quo128(hi, lo, 1e9), int64(ns)).UTC()
137	}
138	
139	// floorMod128 returns t mod y for the signed 128-bit value t = (hi<<64)|lo
140	// and positive y, with the result in [0, y).
141	func floorMod128(hi int64, lo uint64, y int64) uint64 {
142		yu := uint64(y)
143		if hi >= 0 {
144			return rem128(uint64(hi), lo, yu)
145		}
146		// Negate the 128-bit value, take the remainder, and reflect it back
147		// into [0, y) for floored (not truncated) division.
148		mlo := -lo
149		mhi := -uint64(hi)
150		if lo != 0 {
151			mhi--
152		}
153		if r := rem128(mhi, mlo, yu); r != 0 {
154			return yu - r
155		}
156		return 0
157	}
158	
159	// quo128 returns (hi<<64|lo)/y for a signed 128-bit dividend known to be an
160	// exact multiple of y, with a quotient that fits in an int64.
161	func quo128(hi int64, lo uint64, y int64) int64 {
162		yu := uint64(y)
163		if hi >= 0 {
164			q, _ := bits.Div64(uint64(hi), lo, yu)
165			return int64(q)
166		}
167		mlo := -lo
168		mhi := -uint64(hi)
169		if lo != 0 {
170			mhi--
171		}
172		q, _ := bits.Div64(mhi, mlo, yu)
173		return -int64(q)
174	}
175	
176	// rem128 returns (hi<<64 | lo) mod y for unsigned hi, lo and y > 0.
177	func rem128(hi, lo, y uint64) uint64 {
178		if hi >= y {
179			hi %= y
180		}
181		return bits.Rem64(hi, lo, y)
182	}
183	
184	// windowIndex locates the window starting at start in ws, which must be
185	// sorted by window start. The second result reports whether it exists;
186	// when it does not, the index is where it would be inserted to keep ws
187	// sorted, i.e. the first window whose start is not before start.
188	func windowIndex(ws []Window, start time.Time) (int, bool) {
189		sec, nsec := start.Unix(), int64(start.Nanosecond())
190		lo, hi := 0, len(ws)
191		for lo < hi {
192			mid := int(uint(lo+hi) >> 1)
193			s := ws[mid].Start
194			if ss, sn := s.Unix(), int64(s.Nanosecond()); ss < sec || (ss == sec && sn < nsec) {
195				lo = mid + 1
196			} else {
197				hi = mid
198			}
199		}
200		if lo < len(ws) {
201			if s := ws[lo].Start; s.Unix() == sec && int64(s.Nanosecond()) == nsec {
202				return lo, true
203			}
204		}
205		return lo, false
206	}
207	
208	// addTo folds one sample into w. Count saturates at math.MaxInt64 instead
209	// of overflowing; Sum, Min, and Max keep updating afterwards.
210	func addTo(w *Window, value float64) {
211		if w.Count < math.MaxInt64 {
212			w.Count++
213		}
214		w.Sum += value
215		if value < w.Min {
216			w.Min = value
217		}
218		if value > w.Max {
219			w.Max = value
220		}
221	}
222	
223	// Add files a sample into its window. A sample earlier than the most recent
224	// accepted sample is rejected with ErrOutOfOrder and leaves the roller
225	// unchanged; a sample at the same instant is accepted and counted again.
226	//
227	// Concurrent Adds are serialized: each takes effect in the order it
228	// acquires the roller, and the out-of-order check is measured against the
229	// samples accepted before it in that order.
230	func (r *Roller) Add(at time.Time, value float64) error {
231		r.mu.Lock()
232		defer r.mu.Unlock()
233		if r.hasAny && at.Before(r.latest) {
234			return ErrOutOfOrder
235		}
236		r.fileLocked(at, value)
237		r.latest = at
238		r.hasAny = true
239		return nil
240	}
241	
242	// AddBatch files a batch of samples as one atomic unit: either every
243	// sample takes effect or none does. The samples may arrive in any order
244	// and are not checked against each other; several samples at the same
245	// instant are each counted. Each sample is filed into its epoch-aligned
246	// window exactly as Add would file it.
247	//
248	// If any sample predates the most recent sample the roller has already
249	// accepted, the whole batch is rejected with ErrOutOfOrder and the roller
250	// is left unchanged. Otherwise the most-recent marker advances to the
251	// later of its previous value and the newest sample in the batch. A nil
252	// or empty batch is accepted, changes nothing, and does not advance the
253	// marker.
254	//
255	// The batch is atomic with respect to every other call on the roller:
256	// concurrent adds, batches, merges, range reads, and cursor creation
257	// observe the roller wholly before or wholly after the batch.
258	func (r *Roller) AddBatch(samples []Sample) error {
259		if len(samples) == 0 {
260			return nil
261		}
262		r.mu.Lock()
263		defer r.mu.Unlock()
264		// One pass to validate the batch against the accepted marker and find
265		// its newest instant; nothing is filed until every sample is known to
266		// be acceptable, so a rejection leaves the roller untouched.
267		latest := samples[0].At
268		for _, s := range samples {
269			if r.hasAny && s.At.Before(r.latest) {
270				return ErrOutOfOrder
271			}
272			if s.At.After(latest) {
273				latest = s.At
274			}
275		}
276		for _, s := range samples {
277			r.fileLocked(s.At, s.Value)
278		}
279		if r.hasAny && r.latest.After(latest) {
280			latest = r.latest
281		}
282		r.latest = latest
283		r.hasAny = true
284		return nil
285	}
286	
287	// fileLocked folds one sample into its window. The caller must hold mu
288	// and must already have cleared the out-of-order check.
289	func (r *Roller) fileLocked(at time.Time, value float64) {
290		start := r.startOf(at)
291		n := len(r.buckets)
292		switch {
293		case n == 0:
294			r.buckets = append(r.buckets, newBucket(start, value))
295		case !start.Before(r.buckets[n-1].Start):
296			// The common case: the sample lands in the newest window or
297			// just past it, so the sorted order is maintained for free.
298			if r.buckets[n-1].Start.Equal(start) {
299				addTo(&r.buckets[n-1], value)
300			} else {
301				r.buckets = append(r.buckets, newBucket(start, value))
302			}
303		default:
304			// The sample belongs to an older window, which can only happen
305			// after a merge brought in windows past latest. A window that
306			// already exists is updated in place; a new one goes into the
307			// backfill buffer, so inserting it never shifts the tail of
308			// buckets and the cost of a mass backfill does not grow with
309			// the number of windows already accepted.
310			if i, ok := windowIndex(r.buckets, start); ok {
311				addTo(&r.buckets[i], value)
312			} else if i, ok := windowIndex(r.back, start); ok {
313				addTo(&r.back[i], value)
314			} else {
315				r.back = append(r.back, Window{})
316				copy(r.back[i+1:], r.back[i:])
317				r.back[i] = newBucket(start, value)
318				r.maybeFlushBack()
319			}
320		}
321	}
322	
323	// newBucket returns a window holding a single sample.
324	func newBucket(start time.Time, value float64) Window {
325		return Window{Start: start, Count: 1, Sum: value, Min: value, Max: value}
326	}
327	
328	// maybeFlushBack folds the backfill buffer into buckets once it holds at
329	// least half as many windows, so the merge cost amortizes to constant
330	// time per backfilled window. The caller must hold mu.
331	func (r *Roller) maybeFlushBack() {
332		if len(r.back)*2 >= len(r.buckets) {
333			r.buckets = mergeWindows(r.buckets, r.back)
334			r.back = nil
335		}
336	}
337	
338	// mergeWindows returns the sorted union of two window slices, each sorted
339	// by window start, combining the statistics of windows that share a
340	// start: counts and sums add, minimums take the smaller, maximums take
341	// the larger. The result is always a fresh slice.
342	func mergeWindows(a, b []Window) []Window {
343		merged := make([]Window, 0, len(a)+len(b))
344		i, j := 0, 0
345		for i < len(a) && j < len(b) {
346			switch {
347			case a[i].Start.Before(b[j].Start):
348				merged = append(merged, a[i])
349				i++
350			case b[j].Start.Before(a[i].Start):
351				merged = append(merged, b[j])
352				j++
353			default:
354				w := a[i]
355				w.Count = satAdd(w.Count, b[j].Count)
356				w.Sum += b[j].Sum
357				if b[j].Min < w.Min {
358					w.Min = b[j].Min
359				}
360				if b[j].Max > w.Max {
361					w.Max = b[j].Max
362				}
363				merged = append(merged, w)
364				i++
365				j++
366			}
367		}
368		merged = append(merged, a[i:]...)
369		merged = append(merged, b[j:]...)
370		return merged
371	}
372	
373	// Window returns the bucket whose start matches start exactly. The second
374	// result is false when no bucket starts at that instant; no nearby bucket
375	// is substituted. The returned Window is a copy and stays valid no matter
376	// what is filed afterwards.
377	func (r *Roller) Window(start time.Time) (Window, bool) {
378		r.mu.RLock()
379		defer r.mu.RUnlock()
380		if i, ok := windowIndex(r.buckets, start); ok {
381			return r.buckets[i], true
382		}
383		if i, ok := windowIndex(r.back, start); ok {
384			return r.back[i], true
385		}
386		return Window{}, false
387	}
388	
389	// Windows returns all buckets in time order. An empty roller yields an
390	// empty slice. The result is a snapshot of one moment: samples filed after
391	// the call do not alter it.
392	func (r *Roller) Windows() []Window {
393		r.mu.RLock()
394		defer r.mu.RUnlock()
395		if len(r.back) != 0 {
396			return mergeWindows(r.buckets, r.back)
397		}
398		out := make([]Window, len(r.buckets))
399		copy(out, r.buckets)
400		return out
401	}
402	
403	// Range returns the buckets that overlap the half-open interval
404	// [from, to), in time order. The endpoints are attributed to windows by
405	// the same epoch-aligned, left-closed rule Add uses: the first bucket
406	// returned is the one containing from, and a bucket starting exactly at
407	// to is excluded. An interval whose end does not come after its start
408	// yields an empty slice, as does an interval no bucket overlaps. The
409	// result is a snapshot of one moment: samples filed after the call do
410	// not alter it.
411	func (r *Roller) Range(from, to time.Time) []Window {
412		r.mu.RLock()
413		defer r.mu.RUnlock()
414		out := []Window{}
415		if !from.Before(to) {
416			return out
417		}
418		lo := r.startOf(from)
419		i, _ := windowIndex(r.buckets, lo)
420		j, _ := windowIndex(r.back, lo)
421		for {
422			var w Window
423			switch {
424			case i < len(r.buckets) && (j >= len(r.back) || r.buckets[i].Start.Before(r.back[j].Start)):
425				w = r.buckets[i]
426				i++
427			case j < len(r.back):
428				w = r.back[j]
429				j++
430			default:
431				return out
432			}
433			if !w.Start.Before(to) {
434				return out
435			}
436			out = append(out, w)
437		}
438	}
439	
440	// Cursor reads a fixed range of windows in batches. The windows are
441	// snapshot when the cursor is created: samples filed, backfilled, or
442	// merged in afterwards do not alter what the cursor returns, so batched
443	// iteration over a large range never tears, skips, or repeats a window,
444	// and the end of the range is reached deterministically no matter what
445	// is written while the cursor advances.
446	//
447	// A Cursor is safe to advance from multiple goroutines at once; each
448	// batch is handed out exactly once.
449	type Cursor struct {
450		// mu guards pos. windows is fixed at creation and read without the
451		// lock.
452		mu      sync.Mutex
453		windows []Window
454		pos     int
455	}
456	
457	// Cursor returns a cursor over the buckets overlapping the half-open
458	// interval [from, to), selected by the same rule as Range.
459	func (r *Roller) Cursor(from, to time.Time) *Cursor {
460		return &Cursor{windows: r.Range(from, to)}
461	}
462	
463	// Next returns the next batch of up to n windows, in time order. Batches
464	// are consecutive and non-overlapping: together they cover exactly the
465	// windows in the cursor's range. Once the range is exhausted, Next
466	// returns an empty slice and the cursor does not move. A non-positive n
467	// yields an empty slice and does not advance the cursor.
468	func (c *Cursor) Next(n int) []Window {
469		c.mu.Lock()
470		defer c.mu.Unlock()
471		rest := len(c.windows) - c.pos
472		if n <= 0 || rest == 0 {
473			return []Window{}
474		}
475		if n > rest {
476			n = rest
477		}
478		out := make([]Window, n)
479		copy(out, c.windows[c.pos:c.pos+n])
480		c.pos += n
481		return out
482	}
483	
484	// Merge folds other's buckets into this roller: counts and sums add,
485	// minimums take the smaller, maximums take the larger, and buckets only one
486	// side has are carried over as-is. Merging does not affect out-of-order
487	// tracking. It panics with "rollup: nil roller" if other is nil, and
488	// returns ErrWindowMismatch, leaving this roller unchanged, if the window
489	// sizes differ.
490	//
491	// The merge is atomic with respect to every other call on either roller:
492	// concurrent readers see this roller wholly before or wholly after the
493	// merge, and a sample filed into other while the merge runs is either
494	// folded in completely or not at all. If the two rollers merge each other
495	// at the same time, the outcome matches some serial order of the two
496	// merges; neither is lost.
497	func (r *Roller) Merge(other *Roller) error {
498		if other == nil {
499			panic("rollup: nil roller")
500		}
501		if other.window != r.window {
502			return ErrWindowMismatch
503		}
504		if r == other {
505			r.mu.Lock()
506			defer r.mu.Unlock()
507			for _, buckets := range [][]Window{r.buckets, r.back} {
508				for i := range buckets {
509					w := &buckets[i]
510					w.Count = satAdd(w.Count, w.Count)
511					w.Sum += w.Sum
512				}
513			}
514			return nil
515		}
516		// Lock both rollers in ID order so simultaneous merges in
517		// opposite directions cannot deadlock.
518		first, second := r, other
519		if other.id < r.id {
520			first, second = other, r
521		}
522		first.mu.Lock()
523		second.mu.Lock()
524		defer second.mu.Unlock()
525		defer first.mu.Unlock()
526	
527		switch {
528		case len(other.buckets) == 0 && len(other.back) == 0:
529			return nil
530		case len(r.buckets) == 0 && len(r.back) == 0:
531			r.buckets = mergeWindows(other.buckets, other.back)
532			return nil
533		}
534		left, right := r.buckets, other.buckets
535		if len(r.back) != 0 {
536			left = mergeWindows(r.buckets, r.back)
537		}
538		if len(other.back) != 0 {
539			right = mergeWindows(other.buckets, other.back)
540		}
541		// Both sides are sorted by window start, so the merge is one linear
542		// pass and one backing array, no per-bucket copies or lookups.
543		r.buckets = mergeWindows(left, right)
544		r.back = nil
545		return nil
546	}
547	
548	// satAdd returns a + b saturated at math.MaxInt64 instead of overflowing.
549	func satAdd(a, b int64) int64 {
550		if b > math.MaxInt64-a {
551			return math.MaxInt64
552		}
553		return a + b
554	}
