1	package rollup
2	
3	import (
4		"fmt"
5		"testing"
6		"time"
7	)
8	
9	var sinkWindows []Window
10	var sinkWindow Window
11	var sinkOK bool
12	
13	// benchRoller builds a roller with n windows of one sample each, starting
14	// at the Unix epoch.
15	func benchRoller(window time.Duration, n int) *Roller {
16		r := New(window)
17		base := time.Unix(0, 0)
18		for i := 0; i < n; i++ {
19			if err := r.Add(base.Add(time.Duration(i)*window), float64(i)); err != nil {
20				panic(err)
21			}
22		}
23		return r
24	}
25	
26	// BenchmarkAdd measures sustained sample submission; each sample opens a
27	// new window, the append-heavy hot path.
28	func BenchmarkAdd(b *testing.B) {
29		r := New(time.Second)
30		base := time.Unix(0, 0)
31		b.ReportAllocs()
32		b.ResetTimer()
33		for i := 0; i < b.N; i++ {
34			if err := r.Add(base.Add(time.Duration(i)*time.Second), float64(i)); err != nil {
35				b.Fatal(err)
36			}
37		}
38	}
39	
40	// BenchmarkAddSameWindow measures submission into an already-open window,
41	// which must not allocate or grow memory per sample.
42	func BenchmarkAddSameWindow(b *testing.B) {
43		r := New(time.Hour)
44		at := time.Unix(0, 0)
45		b.ReportAllocs()
46		b.ResetTimer()
47		for i := 0; i < b.N; i++ {
48			if err := r.Add(at, float64(i)); err != nil {
49				b.Fatal(err)
50			}
51		}
52	}
53	
54	// BenchmarkAddParallel measures concurrent submission at a single instant,
55	// where every sample is accepted.
56	func BenchmarkAddParallel(b *testing.B) {
57		r := New(time.Second)
58		at := time.Unix(0, 0)
59		b.ReportAllocs()
60		b.ResetTimer()
61		b.RunParallel(func(pb *testing.PB) {
62			for pb.Next() {
63				if err := r.Add(at, 1); err != nil {
64					b.Error(err)
65				}
66			}
67		})
68	}
69	
70	// BenchmarkWindows measures reading out the full window set.
71	func BenchmarkWindows(b *testing.B) {
72		for _, n := range []int{1000, 100000} {
73			b.Run(fmt.Sprintf("n=%d", n), func(b *testing.B) {
74				r := benchRoller(time.Second, n)
75				b.ReportAllocs()
76				b.ResetTimer()
77				for i := 0; i < b.N; i++ {
78					sinkWindows = r.Windows()
79				}
80			})
81		}
82	}
