91			sinkWindow, sinkOK = r.Window(time.Unix(int64(i%n), 0))
92		}
93	}
94	
95	// BenchmarkMerge measures folding two rollers of n windows each together,
96	// both fully overlapping and fully disjoint.
97	func BenchmarkMerge(b *testing.B) {
98		for _, n := range []int{1000, 100000} {
99			src := benchRoller(time.Second, n)
100			b.Run(fmt.Sprintf("overlap/n=%d", n), func(b *testing.B) {
101				b.ReportAllocs()
102				for i := 0; i < b.N; i++ {
103					b.StopTimer()
104					dst := benchRoller(time.Second, n)
105					b.StartTimer()
106					if err := dst.Merge(src); err != nil {
107						b.Fatal(err)
108					}
109				}
