9	func TestRollupBadFactor(t *testing.T) {
10		r := New(time.Second)
11		for _, factor := range []int{0, -1, -100} {
12			func() {
13				defer func() {
14					if got := recover(); got != "rollup: bad factor" {
15						t.Fatalf("factor %d: expected \"rollup: bad factor\" panic, got %v", factor, got)
16					}
17				}()
18				r.Rollup(factor)
19			}()
20		}
21	}
22	
23	func TestRollupFactorOneEqualsRoller(t *testing.T) {
24		r := New(10 * time.Second)
25		for i := int64(0); i < 50; i++ {
26			if err := r.Add(time.Unix(i*7, 0), float64(i)); err != nil {
27				t.Fatal(err)
28			}
29		}
30		// Backfill an older window so the back buffer is in play too: merging
31		// pulls in a window past the latest marker, and a sample between the
32		// marker and that window lands in the backfill buffer.
33		r2 := New(10 * time.Second)
34		if err := r2.Add(time.Unix(1000, 0), -5); err != nil {
35			t.Fatal(err)
36		}
37		if err := r.Merge(r2); err != nil {
38			t.Fatal(err)
39		}
40		if err := r.Add(time.Unix(500, 0), 99); err != nil {
41			t.Fatal(err)
42		}
43	
44		want := r.Windows()
45		got := r.Rollup(1).Range(time.Unix(-1000, 0), time.Unix(2000, 0))
46		if len(got) != len(want) {
47			t.Fatalf("factor 1: got %d windows, want %d", len(got), len(want))
48		}
49		for i := range want {
50			if got[i] != want[i] {
51				t.Fatalf("factor 1: window %d differs: got %+v, want %+v", i, got[i], want[i])
52			}
53		}
54	}
55	
56	func TestRollupMergesCoveredWindows(t *testing.T) {
57		r := New(10 * time.Second)
58		// Coarse windows are 30s wide: [0,30), [30,60), ...
59		samples := []Sample{
60			{time.Unix(0, 0), 1},
61			{time.Unix(5, 0), 2},
62			{time.Unix(15, 0), 3},
63			{time.Unix(25, 0), 4},
64			{time.Unix(35, 0), 10},
65		}
66		if err := r.AddBatch(samples); err != nil {
67			t.Fatal(err)
68		}
69		v := r.Rollup(3)
70	
71		w := v.Window(time.Unix(0, 0))
72		if w.Count != 4 || w.Sum != 10 || w.Min != 1 || w.Max != 4 {
73			t.Fatalf("coarse window 0: %+v", w)
74		}
75		if !w.Start.Equal(time.Unix(0, 0)) {
76			t.Fatalf("coarse start: %v", w.Start)
77		}
78		w = v.Window(time.Unix(30, 0))
79		if w.Count != 1 || w.Sum != 10 || w.Min != 10 || w.Max != 10 {
80			t.Fatalf("coarse window 30: %+v", w)
81		}
82		// No coarse window starts at 60s: zero stats, no error.
83		if w = v.Window(time.Unix(60, 0)); w.Count != 0 || w.Sum != 0 || w.Min != 0 || w.Max != 0 {
84			t.Fatalf("missing coarse window should be zero: %+v", w)
85		}
86		// A start no coarse window begins at also yields zero stats.
87		if w = v.Window(time.Unix(10, 0)); w.Count != 0 {
88			t.Fatalf("exact-match lookup should miss at 10s: %+v", w)
89		}
90	}
91	
92	func TestRollupAlignmentPreEpoch(t *testing.T) {
93		r := New(10 * time.Second)
94		// -5s is in fine window [-10,0), which sits in coarse window [-30,0).
95		if err := r.Add(time.Unix(-5, 0), 7); err != nil {
96			t.Fatal(err)
97		}
98		v := r.Rollup(3)
99		w := v.Window(time.Unix(-30, 0))
100		if w.Count != 1 || w.Sum != 7 {
101			t.Fatalf("coarse window -30: %+v", w)
102		}
103	}
104	
105	func TestRollupRange(t *testing.T) {
106		r := New(time.Minute)
107		for i := int64(0); i < 10; i++ {
108			if err := r.Add(time.Unix(i*60, 0), float64(i)); err != nil {
109				t.Fatal(err)
110			}
111		}
112		v := r.Rollup(5) // 5-minute coarse windows: [0,5), [5,10) minutes
113	
114		// Half-open: from inside the first coarse window, to exactly at the
